VolumeListener.addListener((VolumeKey event) {
    switch (event) {
        case VolumeKey.up:
            print('Volume Up'); break;
        case VolumeKey.down:
            print('Volume Down'); break;
        case VolumeKey.capture:
            print('iOS Hardware Camera Capture'); 
            break;
    }
});
VolumeListener.removeListener();
